WITH cleaned AS (SELECT id, customer_id, device, browser, started_at, country, LENGTH(country) AS country_length, CASE WHEN device = 'desktop' THEN 1 ELSE 0 END AS is_desktop, COALESCE(browser, 'OTHER') AS resolved_browser FROM sessions WHERE browser IS NOT NULL AND device <> 'tablet') SELECT s.id, s.customer_id, s.device, s.browser, s.started_at, s.country, s.country_length, top1.web_event_event_time, top1.page FROM cleaned s JOIN LATERAL (SELECT c.event_time AS web_event_event_time, c.page FROM web_events c WHERE c.session_id = s.id ORDER BY c.duration_sec DESC, c.id DESC LIMIT 1) top1 ON TRUE
